import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import * as platformSchema from "../db/schema";
import { appendOnlyTriggersSql } from "../db/sql";
import { groupMembers, groupRoles, groups, users, type Db } from "../db";
import { loadUser } from "../rbac";
import type { RoleCatalog } from "../registry";

/** Fresh in-memory database with the platform schema plus any app schemas (generated by drizzle-kit). */
export async function createTestDb(...appSchemas: Record<string, unknown>[]): Promise<Db> {
  const { generateSQLiteDrizzleJson, generateSQLiteMigration } = await import("drizzle-kit/api");
  const merged = Object.assign({}, platformSchema, ...appSchemas);
  const statements = await generateSQLiteMigration(await generateSQLiteDrizzleJson({}), await generateSQLiteDrizzleJson(merged));
  const sqlite = new Database(":memory:");
  sqlite.pragma("foreign_keys = ON");
  for (const s of statements) sqlite.exec(s);
  sqlite.exec(appendOnlyTriggersSql);
  return drizzle(sqlite);
}

/** Creates a user in a group that holds `roles`, and returns the resolved CurrentUser. */
export function createTestUser(db: Db, catalog: RoleCatalog, id: string, roles: string[]) {
  db.insert(users).values({ id, email: `${id}@test.local`, displayName: id }).run();
  if (roles.length) {
    const groupId = `g_${id}`;
    db.insert(groups).values({ id: groupId, name: groupId }).run();
    db.insert(groupMembers).values({ groupId, userId: id }).run();
    db.insert(groupRoles).values(roles.map((roleKey) => ({ groupId, roleKey }))).run();
  }
  const user = loadUser(db, catalog, id);
  if (!user) throw new Error("test user not created");
  return user;
}
